// Validar webhook verification do WhatsApp
const queryParams = $input.item.json.query;

// Se for verificação do webhook
if (queryParams && queryParams['hub.mode'] === 'subscribe') {
  if (queryParams['hub.verify_token'] === '{{$env.WHATSAPP_VERIFY_TOKEN}}') {
    return [{
      json: {
        challenge: queryParams['hub.challenge']
      }
    }];
  } else {
    throw new Error('Verify token inválido');
  }
}

// Processar mensagem recebida
const body = $input.item.json.body;

if (!body || !body.entry || !body.entry[0]) {
  return [{ json: { skip: true } }];
}

const entry = body.entry[0];
const changes = entry.changes[0];
const value = changes.value;

if (!value.messages || !value.messages[0]) {
  return [{ json: { skip: true } }];
}

const message = value.messages[0];
const contact = value.contacts ? value.contacts[0] : {};

return [{
  json: {
    from: message.from,
    name: contact.profile?.name || 'Usuário',
    messageId: message.id,
    timestamp: message.timestamp,
    text: message.text?.body || '',
    type: message.type,
    rawMessage: message
  }
}];

// Construir prompt com contexto
const userMessage = $input.first().json.text;
const userName = $input.first().json.name;
const phoneNumber = $input.first().json.from;
const conversationHistory = $input.all()[0]?.json || [];

// System prompt
const systemPrompt = `Você é um assistente virtual atencioso e prestativo.

CONTEXTO:
- Você atende clientes via WhatsApp
- Seu objetivo é ajudar, esclarecer dúvidas e resolver problemas
- Seja cordial, objetivo e use linguagem natural em Português BR

DIRETRIZES:
1. Sempre cumprimente o usuário
2. Entenda a intenção da mensagem
3. Forneça respostas claras e concisas
4. Use emojis quando apropriado 😊
5. Se não souber, seja honesto e ofereça alternativas`;

// Construir array de mensagens
let messages = [
  {
    role: 'system',
    content: systemPrompt
  }
];

// Adicionar histórico (últimas 5 mensagens)
if (Array.isArray(conversationHistory) && conversationHistory.length > 0) {
  conversationHistory.reverse().forEach(msg => {
    messages.push({
      role: msg.role,
      content: msg.content
    });
  });
}

// Adicionar mensagem atual
messages.push({
  role: 'user',
  content: userMessage
});

return [{
  json: {
    messages: messages,
    userPhone: phoneNumber,
    userName: userName,
    userMessage: userMessage
  }
}];

// Extrair resposta do GPT
const gptResponse = $input.first().json;
const assistantMessage = gptResponse.choices[0].message.content;
const tokensUsed = gptResponse.usage.total_tokens;
const userPhone = $input.first().json.userPhone;
const userName = $input.first().json.userName;

return [{
  json: {
    to: userPhone,
    response: assistantMessage,
    tokensUsed: tokensUsed,
    userName: userName
  }
}];
